package io.github.rebrowser.outlook;
import org.junit.Test;
import static org.junit.Assert.*;
import io.github.rebrowser.bootstrap.*;
import io.github.rebrowser.crypto.ObjectAead;
import io.github.rebrowser.core.ResourceBudgets;
import java.io.*;
import java.lang.reflect.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.atomic.*;
/** ACTUAL HOST FS/JCA/immutable RAW read/write. Private synthetic account/source/key/reservation
 * commit flags/DB catalog descriptors ONLY; NO Android SQLite/Keystore/OS owner authority. */
public final class MailObjectStoreHostTest {
 static final class F implements AutoCloseable {
  final Path root=Files.createTempDirectory("mail-object-owned-host-");final AtomicReference<ComponentGate.SourceView> source=new AtomicReference<>(ComponentGate.SourceView.acceptedNative(this,new byte[16]));final ComponentGate gate=ComponentGate.forNativeSource(ProcessRole.MAIN,source::get);final MailAccountCatalog accounts=new MailAccountCatalog(gate.captureDataEpoch(gate.requireBusiness()));final MailAccountCatalog.AccountRef account=accounts.createNativeLocalAccount("synthetic local slot");final MailAccountCatalog.PersistenceScope scope=accounts.capturePersistenceScope(accounts.select(account),1);final MailObjectStore store;final MailDatabase db;final byte[] key=new byte[32];
  F()throws Exception{Constructor<MailObjectStore> s=MailObjectStore.class.getDeclaredConstructor(MailAccountCatalog.PersistenceScope.class,Path[].class,boolean.class);s.setAccessible(true);store=s.newInstance(scope,new Path[]{root},true);Constructor<MailDatabase> d=MailDatabase.class.getDeclaredConstructor(android.database.sqlite.SQLiteDatabase.class,MailAccountCatalog.PersistenceScope.class);d.setAccessible(true);db=d.newInstance(null,scope);}
  ObjectAead.WritePlan plan(byte[] raw)throws Exception{return ObjectAead.freshWrite(new ObjectAead.Limits(64L*1024*1024,64L*1024*1024),ObjectAead.Codec.RAW,ObjectAead.Purpose.ATTACHMENT,1,scope.dataEpoch(),scope.accountId(),raw.length,raw.length,MessageDigest.getInstance("SHA-256").digest(raw));}
  MailDatabase.Reservation reservation(ObjectAead.WritePlan p,boolean committed)throws Exception{Constructor<MailDatabase.Reservation> c=MailDatabase.Reservation.class.getDeclaredConstructor(MailDatabase.class,byte[].class);c.setAccessible(true);MailDatabase.Reservation r=c.newInstance(db,p.metadata().objectId());Field f=MailDatabase.Reservation.class.getDeclaredField("committed");f.setAccessible(true);f.setBoolean(r,committed);return r;}
  MailObjectStore.Prepared seal(byte[] raw)throws Exception{ObjectAead.WritePlan p=plan(raw);return store.sealReservedRaw(reservation(p,true),p,key,new ByteArrayInputStream(raw),()->false);}
  MailDatabase.ObjectRecord record(MailObjectStore.Prepared p,byte[] inline)throws Exception{Constructor<MailDatabase.ObjectRecord> c=MailDatabase.ObjectRecord.class.getDeclaredConstructor(MailDatabase.class,ObjectAead.Metadata.class,byte[].class,String.class,ResourceBudgets.Allocation.class);c.setAccessible(true);return c.newInstance(db,p.metadata,inline,p.fileKey,null);}
  byte[] read(MailObjectStore.Prepared p)throws Exception{try(MailDatabase.ObjectRecord r=record(p,p.inline==null?null:p.inline.clone())){ByteArrayOutputStream out=new ByteArrayOutputStream();store.readVerifiedRawIntoPrivateStage(r,key,out,()->false,()->{});return out.toByteArray();}}
  public void close()throws Exception{try(java.util.stream.Stream<Path> paths=Files.walk(root)){for(Path p:paths.sorted(Comparator.reverseOrder()).toArray(Path[]::new))Files.delete(p);}}
 }
 @Test public void realInlineCipherRoundTripAndExactKnownCommitStageDisposal()throws Exception{try(F f=new F()){byte[] raw={1,2,3,4};MailObjectStore.Prepared p=f.seal(raw);assertNotNull(p.inline);assertNull(p.fileKey);assertArrayEquals(raw,f.read(p));Path stage=f.root.resolve(hex(p.objectId())+".pending");assertTrue(Files.isRegularFile(stage));p.claim(f.db);p.finishKnownDatabaseCommit();assertFalse(Files.exists(stage));}}
 @Test public void largeActualRawImmutableFileRoundTripsWithoutDeclaredBodyAllocation()throws Exception{try(F f=new F()){byte[] raw=new byte[70000];new Random(1).nextBytes(raw);MailObjectStore.Prepared p=f.seal(raw);assertNull(p.inline);assertEquals(hex(p.objectId()),p.fileKey);assertTrue(Files.isRegularFile(f.root.resolve(p.fileKey)));assertFalse(Files.exists(f.root.resolve(p.fileKey+".pending")));assertArrayEquals(raw,f.read(p));}}
 @Test public void reservationCannotEncryptBeforeActualCommitReceipt()throws Exception{try(F f=new F()){byte[] raw={1};ObjectAead.WritePlan p=f.plan(raw);assertThrows(SecurityException.class,()->f.store.sealReservedRaw(f.reservation(p,false),p,f.key,new ByteArrayInputStream(raw),()->false));assertFalse(Files.exists(f.root.resolve(hex(p.metadata().objectId())+".pending")));}}
 @Test public void reservationAndPlanAreOneAttemptEvenAfterSuccess()throws Exception{try(F f=new F()){byte[] raw={1};ObjectAead.WritePlan p=f.plan(raw);MailDatabase.Reservation r=f.reservation(p,true);f.store.sealReservedRaw(r,p,f.key,new ByteArrayInputStream(raw),()->false);assertThrows(SecurityException.class,()->f.store.sealReservedRaw(r,p,f.key,new ByteArrayInputStream(raw),()->false));}}
 @Test public void wrongKeyCannotPublishEvenAnAuthenticatedPrefix()throws Exception{try(F f=new F()){MailObjectStore.Prepared p=f.seal(new byte[]{1,2});try(MailDatabase.ObjectRecord r=f.record(p,p.inline.clone())){byte[] bad=f.key.clone();bad[0]=1;ByteArrayOutputStream privateStage=new ByteArrayOutputStream();assertThrows(GeneralSecurityException.class,()->f.store.readVerifiedRawIntoPrivateStage(r,bad,privateStage,()->false,()->{}));assertEquals(0,privateStage.size());}}}
 @Test public void tamperedInlineCipherFailsActualAead()throws Exception{try(F f=new F()){MailObjectStore.Prepared p=f.seal(new byte[]{1,2});byte[] bad=p.inline.clone();bad[bad.length-1]^=1;try(MailDatabase.ObjectRecord r=f.record(p,bad)){assertThrows(GeneralSecurityException.class,()->f.store.readVerifiedRawIntoPrivateStage(r,f.key,new ByteArrayOutputStream(),()->false,()->{}));}}}
 @Test public void exactCipherEofIsRequiredAndPrefixRemainsPrivateOnFailure()throws Exception{try(F f=new F()){MailObjectStore.Prepared p=f.seal(new byte[]{1,2});try(MailDatabase.ObjectRecord r=f.record(p,Arrays.copyOf(p.inline,p.inline.length+1))){assertThrows(IOException.class,()->f.store.readVerifiedRawIntoPrivateStage(r,f.key,new ByteArrayOutputStream(),()->false,()->{}));}}}
 @Test public void staleSameEpochSourceCannotRetargetOldOwnedFiles()throws Exception{try(F f=new F()){MailObjectStore.Prepared p=f.seal(new byte[]{1});f.source.set(ComponentGate.SourceView.acceptedNative(new Object(),new byte[16]));assertThrows(SecurityException.class,()->f.read(p));}}
 @Test public void nativeAccountSelectionChangeRevokesOldScope()throws Exception{try(F f=new F()){MailObjectStore.Prepared p=f.seal(new byte[]{1});f.accounts.select(f.accounts.createNativeLocalAccount("another"));assertThrows(SecurityException.class,()->f.read(p));}}
 @Test public void unknownDirectoryNodesBlockWritesAndArePreserved()throws Exception{try(F f=new F()){Path unknown=f.root.resolve("unowned");Files.write(unknown,new byte[]{9});assertThrows(IOException.class,()->f.seal(new byte[]{1}));assertArrayEquals(new byte[]{9},Files.readAllBytes(unknown));}}
 @Test public void cancelledReadDoesNotPretendAnyNativeEnd()throws Exception{try(F f=new F()){MailObjectStore.Prepared p=f.seal(new byte[]{1});try(MailDatabase.ObjectRecord r=f.record(p,p.inline.clone())){assertThrows(InterruptedIOException.class,()->f.store.readVerifiedRawIntoPrivateStage(r,f.key,new ByteArrayOutputStream(),()->true,()->{}));}}}
 @Test public void unknownActualInputCloseRetainsCipherAndDoesNotRetryClose()throws Exception{try(F f=new F()){byte[] raw=new byte[70000];ObjectAead.WritePlan p=f.plan(raw);AtomicInteger closes=new AtomicInteger();InputStream input=new ByteArrayInputStream(raw){public void close()throws IOException{closes.incrementAndGet();throw new IOException("synthetic close unknown");}};assertThrows(IOException.class,()->f.store.sealReservedRaw(f.reservation(p,true),p,f.key,input,()->false));assertEquals(1,closes.get());assertTrue(Files.exists(f.root.resolve(hex(p.metadata().objectId()))));}}
 @Test public void fileSymlinkCannotReadAnUnownedReplacement()throws Exception{try(F f=new F()){MailObjectStore.Prepared p=f.seal(new byte[70000]);Path file=f.root.resolve(p.fileKey),foreign=Files.createTempFile("mail-object-foreign-host-",".bin");try{Files.delete(file);Files.createSymbolicLink(file,foreign);assertThrows(IOException.class,()->f.read(p));}finally{Files.deleteIfExists(foreign);}}}
 private static String hex(byte[] bytes){StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return s.toString();}
}
